    text-transform: uppercase;
    text-decoration: none;
    background: var(--yellow);
    color: var(--black);
    border: var(--line) solid var(--black);
    padding: 1rem 1.8rem;
    font-size: 1.1rem;
    letter-spacing: .04em;
    transition: background .15s, color .15s, transform .15s;
  }
  .btn:hover { background: var(--red); color: var(--white); transform: translate(-3px, -3px); box-shadow: 6px 6px 0 var(--black); }
